import type { Lang, SymbolDef } from './types'
import { fieldsFor } from './ratings'
import { portNumbers, pilotNumbers, solenoidNames } from './fluidNames'

/** Fiche pédagogique d'un composant : à quoi il sert, dans quels cas on l'emploie, quels réglages comptent et pourquoi. */
export interface Explain {
  title: string
  what: string
  use: string
  params: { name: string; why: string }[]
  sim: string[]
  tip?: string
}

type L = { fr: string; en: string }
const L = (fr: string, en: string): L => ({ fr, en })
/** paramètre : nom FR, raison FR, nom EN, raison EN */
const P = (n: string, w: string, ne: string, we: string): [L, L] => [L(n, ne), L(w, we)]

interface Card {
  test: (d: SymbolDef) => boolean
  what: L
  use: L
  params?: [L, L][]
  tip?: L
  /** le nom du symbole précède l'explication (familles de récepteurs très variés) */
  named?: boolean
}

const id = (re: RegExp) => (d: SymbolDef) => re.test(d.id)
const name = (re: RegExp) => (d: SymbolDef) => re.test(d.name.fr + ' ' + d.name.en)
const both = (...t: ((d: SymbolDef) => boolean)[]) => (d: SymbolDef) => t.every((f) => f(d))
const any = (...t: ((d: SymbolDef) => boolean)[]) => (d: SymbolDef) => t.some((f) => f(d))

const TAG = P('Repère (ex. KM1, Q1, S2)', 'Le repère identifie l’appareil sur le schéma et relie ses éléments entre eux : une bobine et ses contacts portent le même repère. Respectez la lettre normalisée (K relais/contacteur, Q protection de puissance, S commande, H voyant, M moteur, B capteur, F protection…).', 'Tag (e.g. KM1, Q1, S2)', 'The tag identifies the device on the diagram and links its parts: a coil and its contacts share the same tag. Use the standard letter (K relay/contactor, Q power protection, S control, H lamp, M motor, B sensor, F protection…).')
const VOLTS = P('Tension nominale', 'À choisir égale à la tension du circuit qui l’alimente : trop faible, l’appareil ne fonctionne pas ; trop forte, il est détruit. En simulation, une tension d’alimentation très différente déclenche un avertissement.', 'Rated voltage', 'Choose it equal to the supply voltage of its circuit: too low and the device does not operate; too high and it is destroyed. In the simulator a very different supply voltage raises a warning.')

// ───────────────────────── fiches électriques
const ELEC: Card[] = [
  { test: id(/^sim-ref$/), what: L('Renvoi de feuille : deux renvois de même repère sont le même conducteur, même sur deux feuilles différentes.', 'Sheet link: two links with the same tag are the same conductor, even on two different sheets.'), use: L('Pour continuer un fil d’une page à l’autre d’un grand schéma sans tracer de ligne interminable.', 'To continue a wire from one page to another of a large diagram without drawing an endless line.'), params: [P('Repère du renvoi', 'Les deux extrémités doivent porter exactement le même repère, sinon elles ne sont pas reliées.', 'Link tag', 'Both ends must carry exactly the same tag, otherwise they are not connected.')] },
  { test: id(/^sim-/), what: L('Source de simulation : impose une tension au conducteur auquel elle est reliée (phase L, neutre N, 0 V, 24 V, source réglable monophasée, continue ou triphasée).', 'Simulation source: imposes a voltage on the conductor it is connected to (phase L, neutral N, 0 V, 24 V, adjustable single-phase, DC or three-phase source).'), use: L('C’est le point de départ de tout schéma simulable : sans source, rien n’est alimenté et rien ne peut fonctionner.', 'It is the starting point of every simulable diagram: without a source nothing is powered and nothing can work.'), params: [P('Tension (V)', 'Elle doit être celle prévue pour les récepteurs : 230 V monophasé, 400 V triphasé, 24 V pour la commande. Une tension trop faible ne fait pas coller les bobines, trop forte déclenche des avertissements.', 'Voltage (V)', 'It must be the one the loads are designed for: 230 V single-phase, 400 V three-phase, 24 V for control. Too low and coils do not pick up; too high raises warnings.'), P('Nature (alternatif / continu)', 'Les bobines et les voyants en 24 V continu ne fonctionnent pas sur une source alternative et inversement : choisissez la bonne nature.', 'Type (AC / DC)', '24 V DC coils and lamps do not work on an AC source and vice versa: choose the right type.')] },
  { test: id(/^plc-/), what: L('Automate programmable 8 entrées / 8 sorties : lit des boutons et capteurs, exécute un programme (Grafcet ou Ladder) et commande des bobines, voyants et électrovannes.', 'Programmable controller, 8 inputs / 8 outputs: reads buttons and sensors, runs a program (Grafcet or Ladder) and drives coils, lamps and solenoid valves.'), use: L('Pour automatiser un cycle : le programme remplace une grande partie du câblage en logique à relais. Sorties à relais : peut commuter 24 V ou 230 V ; sorties à transistors : 24 V continu seulement.', 'To automate a cycle: the program replaces much of the relay-logic wiring. Relay outputs can switch 24 V or 230 V; transistor outputs 24 V DC only.'), params: [P('Alimentation L+ / M', 'L’automate doit être alimenté en 24 V continu : sans cela le voyant RUN reste éteint et les sorties ne bougent pas.', 'Supply L+ / M', 'The PLC must be powered at 24 V DC: otherwise the RUN lamp stays off and outputs do not move.'), P('Commun des entrées (COM)', 'Il doit être relié à la source des entrées : sans lui, boutons et capteurs ne sont pas vus.', 'Input common (COM)', 'It must be tied to the input source: without it buttons and sensors are not seen.'), P('Mnémoniques', 'Donner aux entrées et sorties le nom de l’organe (1S2, 1YV14) rend le programme lisible et évite les erreurs.', 'Mnemonics', 'Naming inputs and outputs after the device (1S2, 1YV14) makes the program readable and avoids mistakes.')], tip: L('Dans les propriétés, « Programmer l’automate… » ouvre l’éditeur.', 'In the properties, “Program the controller…” opens the editor.') },
  { test: id(/110_network_supplies|\/terre$|ground|masse/), what: L('Repère d’alimentation ou de mise à la terre : il indique d’où vient la tension (réseau, phases, neutre) ou où le circuit est relié à la terre.', 'Supply or earthing marker: it shows where the voltage comes from (mains, phases, neutral) or where the circuit is earthed.'), use: L('En tête d’un schéma pour représenter le réseau (L1 L2 L3 N PE) et au bas des appareils à relier à la terre (carcasses de moteur, coffrets).', 'At the top of a diagram to represent the mains (L1 L2 L3 N PE) and on equipment that must be earthed (motor frames, enclosures).'), params: [P('Régime de neutre (TT, TN, IT)', 'Il détermine la protection des personnes : en TT on emploie des disjoncteurs différentiels, en TN les protections de surintensité suffisent le plus souvent.', 'Earthing system (TT, TN, IT)', 'It sets personal protection: TT uses residual-current devices, TN usually relies on overcurrent protection.')] },
  { test: id(/114_connections/), what: L('Symbole de liaison : jonction, croisement, raccord ou renvoi de conducteurs.', 'Connection symbol: junction, crossing, joint or link between conductors.'), use: L('Pour montrer que deux fils sont reliés (point) ou simplement se croisent sans contact, ou pour continuer un fil à un autre endroit du schéma.', 'To show that two wires are connected (dot) or merely cross without contact, or to continue a wire elsewhere on the diagram.') },
  { test: id(/120_cables_wiring/), what: L('Câble ou repère de filerie : un câble multiconducteur, un écran ou un repère de désignation.', 'Cable or wiring marker: a multi-core cable, a shield or a designation tag.'), use: L('Pour décrire la liaison physique entre armoire et machine (nombre de conducteurs, couleurs) dans les schémas de câblage.', 'To describe the physical link between cabinet and machine (number of cores, colours) in wiring diagrams.'), params: [P('Section des conducteurs', 'Elle doit supporter le courant du récepteur et rester protégée par un calibre adapté (1,5 mm² → 16 A maximum, 2,5 mm² → 20 A…) pour éviter l’échauffement.', 'Conductor cross-section', 'It must carry the load current and be protected by a suitable rating (1.5 mm² → 16 A max, 2.5 mm² → 20 A…) to avoid overheating.')] },
  { test: id(/130_terminals|borne|bornier/), what: L('Borne ou bornier : point de raccordement entre le câblage de l’armoire et les conducteurs extérieurs.', 'Terminal or terminal block: connection point between cabinet wiring and external conductors.'), use: L('Pour sortir de l’armoire vers les moteurs, capteurs et boutons : on câble chaque fil sur une borne numérotée, ce qui facilite la maintenance et le dépannage.', 'To leave the cabinet towards motors, sensors and buttons: each wire lands on a numbered terminal, which eases maintenance and troubleshooting.'), params: [P('Numéro de borne', 'Il doit correspondre à celui du schéma et de la nomenclature de câblage : c’est ce qui permet de retrouver un fil dans l’armoire.', 'Terminal number', 'It must match the diagram and wiring list: this is how a wire is found in the cabinet.')] },
  { test: id(/140_connectors_plugs/), what: L('Connecteur, prise ou fiche : liaison amovible entre deux parties d’un circuit.', 'Connector, plug or socket: removable link between two parts of a circuit.'), use: L('Pour raccorder rapidement un capteur, un moteur ou un coffret (connecteurs M12, prises 2P+T, SUB-D…) sans toucher au câblage.', 'To connect a sensor, motor or box quickly (M12, 2P+E sockets, D-sub…) without touching the wiring.'), params: [P('Nombre de contacts et brochage', 'Le brochage doit être respecté broche par broche : une inversion alimente le mauvais fil et peut détruire le capteur.', 'Contact count and pinout', 'Respect the pinout pin by pin: a swap powers the wrong wire and can destroy the sensor.')] },
  { test: id(/10_fuses/), what: L('Fusible : protège le circuit en fondant quand le courant dépasse sa valeur, ce qui coupe le circuit définitivement.', 'Fuse: protects the circuit by melting when current exceeds its value, opening the circuit permanently.'), use: L('En tête de circuit pour protéger les câbles et les récepteurs contre les courts-circuits (et les surcharges selon le type). Associé à un relais thermique pour un moteur avec un fusible aM.', 'At the head of a circuit to protect cables and loads against short circuits (and overloads depending on type). Paired with a thermal relay for a motor when using an aM fuse.'), params: [TAG], tip: L('Un fusible fondu se remplace, il ne se réarme pas : en simulation, cliquez dessus pour le remplacer.', 'A blown fuse is replaced, not reset: in the simulator, click it to replace it.') },
  { test: both(id(/12_magneto|11_circuit_breakers/), name(/moteur|motor|GV/i)), what: L('Disjoncteur-moteur : protège un moteur à la fois contre les courts-circuits (déclencheur magnétique) et contre les surcharges (déclencheur thermique réglable). Il sert aussi d’interrupteur de sectionnement.', 'Motor circuit breaker: protects a motor against short circuits (magnetic trip) and overloads (adjustable thermal trip). It also works as an isolating switch.'), use: L('En tête d’un départ moteur, avant le contacteur : à lui seul il remplace fusibles + relais thermique + sectionneur.', 'At the head of a motor starter, before the contactor: on its own it replaces fuses + thermal relay + isolator.'), tip: L('Réglez le thermique sur le courant de la plaque signalétique du moteur.', 'Set the thermal trip to the current on the motor nameplate.') },
  { test: id(/11_circuit_breakers|12_magneto/), what: L('Disjoncteur : protège les câbles et récepteurs en coupant automatiquement le circuit en cas de surcharge ou de court-circuit. Contrairement au fusible, on le réarme.', 'Circuit breaker: protects cables and loads by automatically opening the circuit on overload or short circuit. Unlike a fuse, it can be reset.'), use: L('En tête de chaque circuit (éclairage, prises, commande) ; le calibre se choisit d’après le câble et la charge.', 'At the head of each circuit (lighting, sockets, control); the rating is chosen from the cable and the load.') },
  { test: id(/20_disconnecting_switches/), what: L('Sectionneur ou interrupteur-sectionneur : permet d’isoler visiblement une installation du réseau pour intervenir en sécurité. Il peut couper en charge (interrupteur-sectionneur) ou à vide (sectionneur).', 'Isolator or switch-disconnector: visibly isolates an installation from the mains so that work can be done safely. It can break under load (switch-disconnector) or off load (isolator).'), use: L('À l’origine d’une armoire ou d’une machine, cadenassable pour les consignations.', 'At the origin of a cabinet or machine, lockable for lock-out procedures.') },
  { test: id(/30_thermal_relays/), what: L('Relais thermique : protège un moteur contre les surcharges prolongées en ouvrant un contact quand le courant dépasse son réglage trop longtemps.', 'Thermal relay: protects a motor against prolonged overload by opening a contact when the current exceeds its setting for too long.'), use: L('Monté sous le contacteur, avec un fusible aM ou un disjoncteur magnétique pour les courts-circuits. Son contact 95-96 coupe la bobine du contacteur.', 'Mounted under the contactor, with an aM fuse or magnetic breaker for short circuits. Its 95-96 contact opens the contactor coil.'), tip: L('Le réglage doit être égal au courant nominal de la plaque moteur.', 'The setting must equal the motor nameplate rated current.') },
  { test: id(/50_residual_current/), what: L('Dispositif différentiel : mesure la différence entre le courant aller et retour ; s’il y a une fuite à la terre (une personne qui touche un fil, un défaut d’isolement), il coupe le circuit.', 'Residual-current device: measures the difference between outgoing and returning current; with an earth leakage (a person touching a wire, an insulation fault) it cuts the circuit.'), use: L('En tête des circuits de prises, de salles d’eau et dans tout circuit où des personnes peuvent toucher des masses (protection contre les chocs électriques).', 'At the head of socket circuits, wet rooms and any circuit where people can touch exposed parts (protection against electric shock).') },
  { test: id(/90_overvoltage/), what: L('Parafoudre ou limiteur de surtension : écoule vers la terre les surtensions (foudre, manœuvres) pour protéger l’électronique.', 'Surge arrester: diverts overvoltages (lightning, switching) to earth to protect electronics.'), use: L('En tête d’installation ou près des équipements sensibles (automates, variateurs).', 'At the installation origin or near sensitive equipment (PLCs, drives).') },
  { test: id(/01_coils/), what: L('Bobine de relais ou de contacteur : un électroaimant qui, lorsqu’il est alimenté, fait changer d’état tous les contacts de même repère (c’est l’organe de commande).', 'Relay or contactor coil: an electromagnet which, when powered, changes the state of every contact with the same tag (the control element).'), use: L('Dans un circuit de commande : un bouton ou un capteur alimente la bobine, qui commande ensuite un moteur, un voyant ou un vérin par ses contacts.', 'In a control circuit: a button or sensor powers the coil, which then drives a motor, lamp or cylinder through its contacts.'), params: [TAG, VOLTS], tip: L('La tension de la bobine doit être celle du circuit de commande (24 V, 230 V…).', 'The coil voltage must match the control circuit (24 V, 230 V…).') },
  { test: id(/02_power_contacts/), what: L('Contacts de puissance du contacteur : trois pôles qui établissent le courant d’un moteur triphasé quand la bobine de même repère est alimentée.', 'Contactor power contacts: three poles that make a three-phase motor’s current when the coil with the same tag is powered.'), use: L('Entre la protection (disjoncteur-moteur) et le moteur : ils permettent de commander à distance un récepteur de forte puissance avec un petit circuit de commande.', 'Between the protection (motor breaker) and the motor: they allow a high-power load to be switched remotely by a small control circuit.'), params: [TAG] },
  { test: id(/02_contacts_cross|03_contacts/), what: L('Contact auxiliaire : un contact associé à une bobine de même repère. Normalement ouvert (NO) il se ferme quand la bobine est alimentée ; normalement fermé (NF) il s’ouvre.', 'Auxiliary contact: a contact tied to a coil with the same tag. Normally open (NO) it closes when the coil is powered; normally closed (NF) it opens.'), use: L('Pour l’auto-maintien (contact NO en parallèle du bouton marche), les verrouillages (contact NF d’un contacteur dans la bobine de l’autre) et la signalisation.', 'For latching (NO contact in parallel with the start button), interlocks (NF contact of one contactor in the other’s coil) and signalling.'), params: [TAG] },
  { test: id(/10_transformers/), what: L('Transformateur : abaisse ou élève une tension alternative en isolant galvaniquement le secondaire du primaire.', 'Transformer: steps an AC voltage down or up while galvanically isolating the secondary from the primary.'), use: L('Pour alimenter une commande en 24 V ou 48 V depuis le 230/400 V (sécurité) ou adapter une tension à un récepteur.', 'To supply a control circuit at 24 V or 48 V from 230/400 V (safety) or to match a voltage to a load.'), params: [P('Tension secondaire', 'C’est la tension fournie aux récepteurs de commande ; choisissez-la égale à leur tension nominale (24 V le plus souvent).', 'Secondary voltage', 'It is the voltage supplied to control devices; choose it equal to their rated voltage (usually 24 V).'), P('Puissance (VA)', 'Doit dépasser la somme des puissances des bobines et voyants alimentés, avec une marge (le simulateur avertit à plus de 80 %).', 'Power (VA)', 'Must exceed the sum of the powers of coils and lamps supplied, with margin (the simulator warns above 80 %).')] },
  { test: id(/30_power_supplies|40_uninterruptible/), what: L('Alimentation : convertit le réseau alternatif en tension continue stabilisée (24 V le plus souvent) pour la commande, les capteurs et les automates.', 'Power supply: converts the AC mains to a regulated DC voltage (usually 24 V) for control, sensors and PLCs.'), use: L('En tête de la partie commande d’une armoire ; protégez son entrée et sa sortie.', 'At the head of the control section of a cabinet; protect its input and output.'), params: [P('Tension et courant de sortie', 'La tension doit être celle des capteurs et automates ; le courant doit couvrir la somme de leurs consommations avec 20 à 30 % de marge.', 'Output voltage and current', 'The voltage must match sensors and PLCs; the current must cover the sum of their consumption with 20–30 % margin.')] },
  { test: id(/340_converters_inverters\/10|340_converters/), what: L('Convertisseur : transforme la nature de l’énergie électrique (alternatif ↔ continu, variation de fréquence, redressement).', 'Converter: changes the nature of electrical energy (AC ↔ DC, frequency variation, rectification).'), use: L('Pour piloter la vitesse d’un moteur (variateur) ou alimenter un circuit continu depuis le réseau alternatif.', 'To control motor speed (drive) or feed a DC circuit from the AC mains.') },
  { test: id(/20_current_tansformers|15_measuring/), what: L('Transformateur ou transducteur de mesure : ramène un courant ou une tension élevés à une valeur mesurable sans contact électrique direct.', 'Measuring transformer or transducer: scales a high current or voltage down to a measurable value without direct electrical contact.'), use: L('Pour alimenter un ampèremètre, une protection ou un automate à partir d’un courant de fort calibre.', 'To feed an ammeter, a protection relay or a PLC from a high-rated current.') },
  { test: id(/01_human_machine_interface/), what: L('Interface homme-machine (IHM) : écran tactile permettant à l’opérateur de commander et visualiser la machine.', 'Human-machine interface (HMI): touchscreen letting the operator control and monitor the machine.'), use: L('Sur les machines automatisées : choix de mode, réglage de paramètres, affichage des défauts.', 'On automated machines: mode selection, parameter setting, fault display.') },
  { test: id(/11_optical_signaling/), what: L('Voyant lumineux : signale un état (marche, défaut, présence tension) par une lampe allumée.', 'Pilot lamp: indicates a status (running, fault, voltage present) with a lit lamp.'), use: L('Sur la porte d’une armoire ou le pupitre : vert = marche, rouge = défaut ou arrêt, jaune = alerte, blanc = information.', 'On a cabinet door or console: green = running, red = fault or stop, yellow = warning, white = information.'), params: [TAG, VOLTS, P('Puissance', 'Très faible (1 à 3 W) ; elle sert à calculer le courant et la charge de l’alimentation.', 'Power', 'Very small (1–3 W); used to compute current and supply load.')] },
  { test: id(/12_acoustic/), what: L('Signalisation sonore (avertisseur, sirène, buzzer) : alerte par un son.', 'Audible signalling (horn, siren, buzzer): alerts by sound.'), use: L('Pour signaler un défaut ou un démarrage imminent de machine.', 'To signal a fault or an imminent machine start.'), params: [TAG, VOLTS] },
  { test: both(id(/20_push_buttons/), name(/urgence|emergency/i)), what: L('Arrêt d’urgence : bouton coup de poing rouge qui, une fois enfoncé, reste verrouillé et coupe la commande.', 'Emergency stop: red mushroom button which, once pressed, stays latched and cuts the control.'), use: L('Sur toute machine dangereuse, accessible à l’opérateur ; son contact NF est en série dans la commande pour couper même en cas de fil coupé (sécurité positive).', 'On any hazardous machine, within the operator’s reach; its NF contact is in series in the control so it cuts even if a wire breaks (fail-safe).'), params: [TAG], tip: L('Un arrêt d’urgence se déverrouille par rotation ou traction ; il ne redémarre jamais seul.', 'An emergency stop is released by turning or pulling; it never restarts by itself.') },
  { test: id(/20_push_buttons/), what: L('Bouton poussoir : contact qui change d’état tant qu’on appuie et revient au repos dès qu’on relâche (contact à rappel).', 'Push button: contact that changes state while pressed and returns to rest when released (spring return).'), use: L('Pour donner un ordre ponctuel : marche (NO, vert), arrêt (NF, rouge). Avec un contact d’auto-maintien, une impulsion lance un cycle qui continue seul.', 'To give a momentary command: start (NO, green), stop (NC, red). With a latching contact, one pulse starts a cycle that continues on its own.'), params: [TAG], tip: L('L’arrêt se câble en NF : si le fil est coupé, la machine s’arrête (sécurité).', 'Stop is wired NC: if the wire breaks the machine stops (fail-safe).') },
  { test: id(/21_selector_switches/), what: L('Sélecteur : commutateur à plusieurs positions maintenues (manuel/auto, 1-0-2, marche avant/arrière).', 'Selector switch: switch with several maintained positions (manual/auto, 1-0-2, forward/reverse).'), use: L('Pour choisir un mode de fonctionnement ou un sens de rotation.', 'To choose an operating mode or rotation direction.'), params: [TAG] },
  { test: id(/25_lever_switches/), what: L('Commande à manette ou levier : interrupteur actionné par un levier, avec ou sans maintien.', 'Lever switch: switch operated by a lever, with or without latching.'), use: L('Sur des engins ou des pupitres de commande (grue, pont roulant).', 'On machines or control desks (crane, hoist).'), params: [TAG] },
  { test: id(/01_sensors_capacitive|02_sensors_inductive/), what: L('Détecteur de proximité : détecte une pièce sans la toucher. Inductif = métaux uniquement ; capacitif = tous matériaux, liquides, poudres.', 'Proximity sensor: detects a part without touching it. Inductive = metals only; capacitive = any material, liquids, powders.'), use: L('Pour détecter la présence d’une pièce, une position de bout de course ou compter des objets, sans usure mécanique.', 'To detect part presence, an end-of-travel position or count objects without mechanical wear.'), params: [P('Portée de détection', 'Distance maximale entre la pièce et le capteur : elle dépend du métal détecté et du diamètre du capteur ; respectez-la pour une détection fiable.', 'Sensing distance', 'Maximum distance between part and sensor: it depends on the metal and sensor diameter; respect it for reliable detection.'), P('Technologie de sortie (PNP / NPN, 2/3 fils)', 'Elle doit correspondre à l’entrée de l’automate : un capteur PNP se branche sur des entrées « sink » (le plus courant en Europe).', 'Output type (PNP / NPN, 2/3-wire)', 'It must match the PLC input: a PNP sensor goes to sinking inputs (most common in Europe).'), TAG], tip: L('Un capteur 3 fils a une alimentation (+/0 V) et une sortie signal.', 'A 3-wire sensor has a supply (+/0 V) and a signal output.') },
  { test: id(/03_sensors_magnetic/), what: L('Capteur magnétique (reed ou à effet Hall) : détecte l’aimant porté par un piston de vérin ou une pièce.', 'Magnetic sensor (reed or Hall effect): detects the magnet carried by a cylinder piston or part.'), use: L('Pour connaître la position d’un vérin pneumatique sans le toucher : on le fixe sur le tube du vérin.', 'To know a pneumatic cylinder position without touching it: it is clamped on the cylinder tube.'), params: [TAG] },
  { test: id(/04_sensors_optical|60_timers/), what: L('Capteur optique (barrage, reflex, proximité) : détecte un objet par l’interruption ou la réflexion d’un faisceau lumineux.', 'Optical sensor (through-beam, retro-reflective, diffuse): detects an object by interruption or reflection of a light beam.'), use: L('Pour détecter des objets de toute nature (carton, plastique) à plus grande distance qu’un capteur inductif.', 'To detect objects of any kind (cardboard, plastic) at a greater distance than an inductive sensor.'), params: [P('Portée', 'Les capteurs en barrage portent le plus loin ; les modèles à réflexion dépendent de la couleur et de la brillance de l’objet.', 'Range', 'Through-beam sensors reach furthest; reflective models depend on the object’s colour and gloss.'), TAG] },
  { test: id(/1[1-6]_sensors_/), what: L('Capteur de grandeur physique (débit, niveau, pression, humidité, température, ultrasons) : traduit une grandeur du process en signal électrique.', 'Physical-quantity sensor (flow, level, pressure, humidity, temperature, ultrasonic): converts a process quantity to an electrical signal.'), use: L('Pour surveiller ou réguler un procédé : niveau de cuve, pression d’un réseau d’air, température d’un four.', 'To monitor or regulate a process: tank level, air network pressure, oven temperature.'), params: [P('Étendue de mesure', 'Elle doit couvrir les valeurs réelles du procédé avec marge, sans dépasser la limite de surcharge du capteur.', 'Measuring range', 'It must cover the real process values with margin without exceeding the sensor overload limit.'), P('Signal de sortie (TOR, 4-20 mA, 0-10 V)', 'Il doit correspondre à l’entrée de l’automate ; le 4-20 mA résiste mieux aux perturbations et détecte un fil coupé (0 mA).', 'Output signal (on/off, 4–20 mA, 0–10 V)', 'It must match the PLC input; 4–20 mA resists interference better and detects a broken wire (0 mA).'), TAG] },
  { test: id(/ils_no$/), what: L('Capteur reed (interrupteur à lame souple, ILS) : deux lames métalliques dans une ampoule de verre qui se touchent quand un aimant s’approche. Il détecte la présence de l’aimant porté par le piston d’un vérin, sans contact mécanique.', 'Reed sensor (reed switch): two metal blades in a glass capsule that touch when a magnet comes close. It detects the magnet carried by a cylinder piston with no mechanical contact.'), use: L('Pour connaître la position d’un vérin : un capteur fixé près de la rentrée (1S1) et un près de la sortie (1S2) servent de fins de course et alimentent les entrées de l’automate. Il se pose sur le vérin (réglage « Détecteur de vérin »).', 'To know a cylinder position: one sensor near retraction (1S1) and one near extension (1S2) act as limit switches and feed the PLC inputs. It is placed on the cylinder (“Cylinder sensor” setting).'), params: [TAG, P('Vérin détecté et position (%)', '0 % = vérin rentré, 100 % = sorti : c’est ce qui ferme le contact pendant la simulation.', 'Cylinder and position (%)', '0 % = retracted, 100 % = extended: this closes the contact during simulation.'), P('Courant et tension de coupure', 'Le contact reed est fragile : il supporte quelques dizaines de mA sous 24 V ; le brancher directement sur une bobine de forte puissance le fait coller ou brûler (on l’utilise sur une entrée d’automate).', 'Switching current and voltage', 'A reed contact is fragile: it handles tens of mA at 24 V; wiring it directly to a high-power coil makes it weld or burn (use it on a PLC input).')], tip: L('Montez les capteurs sur la rainure du tube du vérin et réglez leur position sur la course.', 'Mount the sensors in the cylinder tube groove and set their position along the stroke.') },
  { test: id(/41_limit_switches/), what: L('Détecteur de position : contact fermé ou ouvert selon la position d’une partie mobile (galet poussé par une came, aimant d’un piston). Les fins de course signalent le bout de course d’un vérin ou d’une machine.', 'Position detector: contact open or closed depending on a moving part’s position (roller pushed by a cam, piston magnet). Limit switches signal the end of travel of a cylinder or machine.'), use: L('Dans un cycle automatique : le détecteur de fin de sortie d’un vérin déclenche l’étape suivante. À poser sur le vérin (réglage « Détecteur de vérin »).', 'In an automatic cycle: a cylinder end-of-stroke detector triggers the next step. Place it on the cylinder (“Cylinder sensor” setting).'), params: [TAG, P('Vérin détecté et position (%)', '0 % = vérin rentré, 100 % = sorti : c’est ce qui ferme le contact pendant la simulation.', 'Cylinder and position (%)', '0 % = retracted, 100 % = extended: this closes the contact during simulation.')], tip: L('Un contact NO se ferme à la détection ; un NF s’ouvre : préférez le NF pour les sécurités.', 'A NO contact closes on detection; a NC opens: prefer NC for safety functions.') },
  { test: id(/70_meters_measuring/), what: L('Appareil de mesure (voltmètre, ampèremètre, compteur, wattmètre…) : affiche une grandeur électrique.', 'Measuring device (voltmeter, ammeter, counter, wattmeter…): displays an electrical quantity.'), use: L('Pour contrôler une tension, un courant ou une énergie sur un tableau.', 'To check a voltage, current or energy on a panel.'), params: [P('Calibre', 'Il doit dépasser la valeur mesurée : un calibre trop petit sature l’appareil, trop grand rend la lecture imprécise.', 'Range', 'It must exceed the measured value: too small saturates the device, too large makes the reading imprecise.')] },
  { test: id(/80_encoder/), what: L('Codeur : capteur de position ou de vitesse angulaire (impulsions ou valeur absolue) monté sur un arbre.', 'Encoder: angular position or speed sensor (pulses or absolute value) mounted on a shaft.'), use: L('Pour positionner précisément un axe ou mesurer la vitesse d’un moteur.', 'To position an axis accurately or measure motor speed.'), params: [P('Résolution (impulsions par tour)', 'Plus elle est élevée, plus la position est précise ; elle fixe aussi la fréquence maximale que l’entrée de comptage doit accepter.', 'Resolution (pulses per turn)', 'The higher it is, the more precise the position; it also sets the maximum frequency the counting input must accept.')] },
  { test: id(/10_engines/), what: L('Moteur électrique : transforme l’énergie électrique en mouvement de rotation.', 'Electric motor: converts electrical energy into rotation.'), use: L('Pour entraîner pompes, ventilateurs, convoyeurs. Un moteur triphasé asynchrone démarre en direct via un contacteur ou avec un variateur.', 'To drive pumps, fans, conveyors. A three-phase induction motor starts direct-on-line through a contactor or with a drive.'), params: [P('Puissance (kW) et courant nominal', 'Ils figurent sur la plaque signalétique et servent à régler la protection thermique et à choisir contacteur, câble et disjoncteur.', 'Power (kW) and rated current', 'They are on the nameplate and are used to set thermal protection and to choose contactor, cable and breaker.'), P('Couplage étoile / triangle', 'Le moteur doit être couplé selon la tension du réseau (ex. 230/400 V : triangle sur 230 V, étoile sur 400 V), sinon il surchauffe ou ne fournit pas sa puissance.', 'Star / delta connection', 'The motor must be connected according to the mains voltage (e.g. 230/400 V: delta on 230 V, star on 400 V), otherwise it overheats or lacks power.'), P('Rapport Id/In', 'Le courant de démarrage vaut 5 à 8 fois le courant nominal : il impose une courbe D ou un fusible aM.', 'Id/In ratio', 'Starting current is 5–8 times rated current: it requires a D curve or an aM fuse.'), TAG] },
  { test: id(/20_valves/), what: L('Électrovanne (côté électrique) : bobine d’un distributeur qui, alimentée, déplace le tiroir de la vanne.', 'Solenoid valve (electrical side): coil of a valve that moves the valve spool when powered.'), use: L('À relier à une sortie d’automate ou à un contact de relais pour commander un vérin pneumatique ou hydraulique.', 'To be wired to a PLC output or relay contact to command a pneumatic or hydraulic cylinder.'), params: [P('Repère de la bobine (ex. 1YV14)', 'Il doit être identique à celui du distributeur sur le schéma pneumatique : c’est ce lien qui fait bouger le tiroir en simulation. 14 relie 1→4, 12 relie 1→2.', 'Coil tag (e.g. 1YV14)', 'It must be identical to the valve on the pneumatic diagram: this link moves the spool in the simulation. 14 connects 1→4, 12 connects 1→2.'), VOLTS] },
  { test: id(/30_brakes/), what: L('Frein ou embrayage électromagnétique : immobilise ou libère un arbre quand sa bobine est alimentée ou coupée.', 'Electromagnetic brake or clutch: holds or releases a shaft when its coil is powered or cut.'), use: L('Sur les moteurs de levage : frein à manque de courant qui retient la charge si l’alimentation disparaît.', 'On hoist motors: spring-applied brake that holds the load if power is lost.'), params: [TAG, VOLTS] },
  { test: id(/50_heatings/), what: L('Résistance chauffante : transforme l’énergie électrique en chaleur.', 'Heating element: converts electrical energy into heat.'), use: L('Fours, chauffage de cuve, étuves ; commandée par contacteur et régulée par une sonde de température.', 'Ovens, tank heating, drying cabinets; switched by a contactor and regulated by a temperature probe.'), params: [P('Puissance (W)', 'Détermine le courant absorbé (I = P / U) et donc le calibre de protection et la section de câble.', 'Power (W)', 'Sets the absorbed current (I = P / U) and therefore the protection rating and cable section.'), TAG] },
  { test: id(/60_lightings/), what: L('Luminaire : lampe d’éclairage alimentée par le circuit.', 'Luminaire: lighting lamp supplied by the circuit.'), use: L('Pour l’éclairage de locaux ou de machines, commandé par interrupteur, détecteur ou télérupteur.', 'For room or machine lighting, controlled by a switch, sensor or impulse relay.'), params: [TAG, VOLTS] },
  { test: id(/70_servomoteur/), what: L('Servomoteur : actionneur de position à fin de course, qui ouvre ou ferme une vanne ou un volet.', 'Servomotor: position actuator with end limits that opens or closes a valve or damper.'), use: L('Pour la régulation de chauffage, ventilation, vannes motorisées.', 'For heating, ventilation and motorised-valve control.'), params: [TAG, VOLTS] },
  { test: id(/392_generators|20_power_units|30_batteries|70_voltage_current/), what: L('Source d’énergie : générateur, batterie ou source de tension / courant.', 'Energy source: generator, battery or voltage / current source.'), use: L('Pour représenter l’alimentation d’un circuit isolé du réseau (secours, mobile, essai).', 'To represent the supply of a circuit isolated from the mains (back-up, mobile, test).'), params: [P('Tension et capacité', 'La tension doit correspondre au récepteur ; la capacité (Ah) fixe l’autonomie.', 'Voltage and capacity', 'Voltage must match the load; capacity (Ah) sets the autonomy.')] },
  { test: id(/01_resistors/), what: L('Résistance : limite le courant ou divise une tension (loi d’Ohm : U = R × I).', 'Resistor: limits current or divides a voltage (Ohm’s law: U = R × I).'), use: L('Pour protéger une LED, polariser un transistor, former un pont diviseur.', 'To protect an LED, bias a transistor, build a voltage divider.'), params: [P('Valeur (Ω) et puissance (W)', 'La valeur fixe le courant ; la puissance dissipée (R × I²) ne doit pas dépasser la puissance admissible, sinon la résistance chauffe et brûle.', 'Value (Ω) and power (W)', 'The value sets the current; the dissipated power (R × I²) must not exceed the rating or the resistor overheats.')] },
  { test: id(/02_capacitors/), what: L('Condensateur : stocke de l’énergie électrique ; il bloque le continu et laisse passer l’alternatif.', 'Capacitor: stores electrical energy; blocks DC and passes AC.'), use: L('Lissage d’alimentation, filtrage, démarrage de moteur monophasé, compensation d’énergie réactive.', 'Supply smoothing, filtering, single-phase motor starting, reactive power compensation.'), params: [P('Capacité (F) et tension maximale', 'La capacité fixe l’effet de lissage ; la tension d’emploi doit rester inférieure à la tension nominale, sinon le condensateur claque.', 'Capacitance (F) and maximum voltage', 'Capacitance sets the smoothing effect; operating voltage must stay below the rating or the capacitor fails.')] },
  { test: id(/03_inductors|09_disturbances/), what: L('Inductance (bobine) ou composant antiparasite : s’oppose aux variations de courant.', 'Inductor (coil) or interference suppressor: opposes current variations.'), use: L('Filtrage, limitation de courant, antiparasitage d’alimentations et de bobines.', 'Filtering, current limiting, supply and coil interference suppression.') },
  { test: id(/11_diodes/), what: L('Diode : ne laisse passer le courant que dans un sens (anode → cathode). Variantes : Zener (stabilise une tension), LED (émet de la lumière).', 'Diode: lets current through in one direction only (anode → cathode). Variants: Zener (stabilises a voltage), LED (emits light).'), use: L('Redressement, protection contre les inversions de polarité, diode de roue libre aux bornes d’une bobine continue, signalisation (LED).', 'Rectification, reverse-polarity protection, flyback diode across a DC coil, signalling (LED).'), params: [P('Tension inverse et courant maximum', 'Elle doit dépasser la tension à bloquer, sinon la diode claque en inverse.', 'Reverse voltage and maximum current', 'It must exceed the voltage to block, otherwise the diode breaks down in reverse.')] },
  { test: id(/12_transistors|13_thyristors/), what: L('Transistor ou thyristor : composant à semi-conducteur qui commande un courant important avec un petit signal (interrupteur électronique ou amplificateur).', 'Transistor or thyristor: semiconductor that controls a large current with a small signal (electronic switch or amplifier).'), use: L('Sorties d’automates, variateurs, commande de puissance sans pièce mobile.', 'PLC outputs, drives, power control with no moving parts.'), params: [P('Tension et courant maximaux', 'Ils définissent la charge que le composant peut commander ; les dépasser le détruit.', 'Maximum voltage and current', 'They define the load the component can switch; exceeding them destroys it.')] },
  { test: id(/24piezo|31_integrated|91_computer/), what: L('Composant électronique intégré (circuit intégré, quartz, interface informatique).', 'Integrated electronic component (IC, crystal, computer interface).'), use: L('Pour représenter des fonctions logiques, de traitement ou de communication dans une carte.', 'To represent logic, processing or communication functions on a board.') },
  { test: id(/41_PLC/), what: L('Automate programmable (API) : calculateur industriel qui lit des entrées (boutons, capteurs), exécute un programme et pilote des sorties (bobines, voyants, électrovannes).', 'Programmable logic controller (PLC): industrial computer that reads inputs (buttons, sensors), runs a program and drives outputs (coils, lamps, solenoid valves).'), use: L('Pour automatiser un cycle : le programme (Grafcet ou Ladder) remplace une grande partie du câblage en logique à relais.', 'To automate a cycle: the program (Grafcet or Ladder) replaces much of the relay-logic wiring.'), params: [P('Alimentation L+ / M', 'L’automate doit être alimenté (24 V continu) pour fonctionner ; sans cela le voyant RUN reste éteint et les sorties ne bougent pas.', 'Supply L+ / M', 'The PLC must be powered (24 V DC) to operate; otherwise the RUN lamp stays off and outputs do not move.'), P('Entrées I0.x et sorties Q0.x', 'Chaque entrée se relie à un bouton ou capteur ; chaque sortie à un récepteur. Les noms donnés (mnémoniques) rendent le programme lisible.', 'Inputs I0.x and outputs Q0.x', 'Each input goes to a button or sensor; each output to a load. Given names (mnemonics) make the program readable.')], tip: L('Cliquez sur « Programmer l’automate » dans les propriétés pour ouvrir l’éditeur.', 'Click “Program the controller” in the properties to open the editor.') },
  { test: id(/20_home_appliances/), named: true, what: L('récepteur de l’installation domestique ou tertiaire (appareil de chauffage, de cuisson, de froid, de ventilation, d’éclairage…), alimenté par son propre circuit.', 'consumer of a home or commercial installation (heating, cooking, cooling, ventilation, lighting…) fed by its own circuit.'), use: L('Pour établir le schéma d’un logement ou d’un local : on repère chaque récepteur, on lui affecte un circuit protégé par un disjoncteur et on vérifie la puissance totale.', 'To draw the diagram of a dwelling or premises: identify each load, give it a circuit protected by a breaker and check the total power.'), params: [P('Puissance (W)', 'Elle détermine le courant (I = P / U) donc le calibre du disjoncteur et la section du câble (ex. plaques de cuisson : circuit spécialisé 32 A en 6 mm²).', 'Power (W)', 'It sets the current (I = P / U) and therefore the breaker rating and cable section (e.g. hob: dedicated 32 A circuit in 6 mm²).'), P('Circuit spécialisé et différentiel 30 mA', 'Les gros appareils (four, lave-linge, chauffe-eau) ont un circuit dédié ; tous les circuits d’un logement sont protégés par un différentiel 30 mA pour la sécurité des personnes.', 'Dedicated circuit and 30 mA RCD', 'Large appliances (oven, washing machine, water heater) have a dedicated circuit; all dwelling circuits are protected by a 30 mA RCD for personal safety.')] },
  { test: id(/30_architectural/), named: true, what: L('équipement d’une installation électrique de bâtiment (prise, interrupteur, point lumineux, tableau, boîte de dérivation) tel qu’il se dessine sur un plan.', 'building electrical installation item (socket, switch, light point, panel, junction box) as drawn on a plan.'), use: L('Sur un plan d’architecte ou un schéma unifilaire : on y place prises et points lumineux pièce par pièce pour définir les circuits.', 'On an architectural plan or single-line diagram: place sockets and light points room by room to define the circuits.'), params: [P('Hauteur et nombre de points', 'Les règles d’installation (NF C 15-100) imposent un nombre minimal de prises par pièce et des hauteurs d’implantation (accessibilité).', 'Height and number of points', 'Installation rules (NF C 15-100) impose a minimum number of sockets per room and mounting heights (accessibility).')] },
  { test: id(/25_V\.D\.I/), named: true, what: L('élément du réseau voix-données-images : prise RJ45, câble réseau, répartiteur TV, antenne ou panneau de brassage.', 'voice-data-image network item: RJ45 socket, network cable, TV splitter, antenna or patch panel.'), use: L('Pour dessiner le câblage courants faibles d’un logement ou d’un local : internet, téléphonie, télévision.', 'To draw the low-voltage wiring of a dwelling or premises: internet, telephony, television.'), params: [P('Catégorie de câble et débit', 'Pour le réseau, un câble catégorie 6 ou plus permet de passer le gigabit ; une catégorie trop faible limite le débit.', 'Cable category and speed', 'For networks, category 6 or better supports gigabit; a lower category limits speed.')] },
  { test: id(/40_meters/), named: true, what: L('appareil de comptage ou de tableau : compteur d’énergie, disjoncteur de branchement, tableau de comptage.', 'metering or panel device: energy meter, service breaker, metering panel.'), use: L('À l’origine d’une installation : le compteur mesure l’énergie consommée et le disjoncteur de branchement limite la puissance souscrite.', 'At the installation origin: the meter records energy used and the service breaker limits the contracted power.') },
  { test: id(/10_resistors|20_capacitors|30_inductors/), named: true, what: L('composant passif de base de l’électronique (résistance, condensateur ou inductance).', 'basic passive electronic component (resistor, capacitor or inductor).'), use: L('Dans les cartes et filtres : limiter un courant, lisser une tension, filtrer un signal.', 'In boards and filters: limit current, smooth voltage, filter a signal.'), params: [P('Valeur et tolérance', 'La valeur fixe le comportement du montage ; la tolérance (1 %, 5 %…) dit de combien elle peut s’écarter.', 'Value and tolerance', 'The value sets the circuit behaviour; tolerance (1 %, 5 %…) says how far it may deviate.')] },
  { test: id(/450_high_voltage/), what: L('Appareil haute tension (contacteur, disjoncteur débrochable) : même fonction que son équivalent basse tension, pour des réseaux au-delà de 1 kV.', 'High-voltage device (contactor, withdrawable breaker): same function as its low-voltage equivalent, for networks above 1 kV.'), use: L('Cellules et postes HTA ; manœuvres réservées à du personnel habilité.', 'MV cells and substations; operation reserved for authorised staff.') },
]

// ───────────────────────── fiches fluides

const up = (x: string) => x.charAt(0).toUpperCase() + x.slice(1)

function fluidCard(d: SymbolDef, lang: Lang): { what: L; use: L; params: [L, L][]; tip?: L } | null {
  const f = d.fluid
  const hyd = d.domain === 'hydraulic'
  const fluid = hyd ? L('d’huile sous pression', 'of pressurised oil') : L('d’air comprimé', 'of compressed air')
  const press = P('Pression de service', hyd ? 'Elle doit rester inférieure à la pression maximale du composant ; les circuits hydrauliques travaillent de 50 à 350 bar, avec un limiteur de pression pour se protéger.' : 'Un circuit pneumatique travaille en général à 6 bar ; un composant dimensionné pour moins risque d’éclater, trop de pression gaspille de l’énergie.', 'Operating pressure', hyd ? 'It must stay below the component’s maximum; hydraulic circuits run at 50–350 bar with a relief valve for protection.' : 'A pneumatic circuit usually runs at 6 bar; a lower-rated component may burst, too much pressure wastes energy.')
  if (!f) return null
  switch (f.k) {
    case 'fsource':
      return { what: L(`Source ${hyd ? 'hydraulique' : 'd’air comprimé'} : alimente le circuit en fluide sous pression (symbole de l’arrivée de pression).`, 'Supply: feeds the circuit with pressurised fluid (pressure inlet symbol).'), use: L('Au point d’entrée du circuit : réseau d’air de l’usine, compresseur, groupe hydraulique.', 'At the circuit entry: factory air network, compressor, power pack.'), params: [press] }
    case 'fsink':
      return /silencieux|silencer/i.test(d.name.fr + d.name.en)
        ? { what: L('Silencieux : laisse sortir l’air des échappements à l’atmosphère en réduisant fortement le bruit.', 'Silencer: lets exhaust air escape to atmosphere while greatly reducing noise.'), use: L('Sur les orifices d’échappement (3, 5) des distributeurs et des vérins.', 'On valve and cylinder exhaust ports (3, 5).'), params: [P('Débit d’échappement', 'Un silencieux trop petit étrangle l’échappement et ralentit le vérin ; un silencieux réglable sert aussi de limiteur de débit à l’échappement.', 'Exhaust flow', 'An undersized silencer chokes the exhaust and slows the cylinder; an adjustable one also serves as an exhaust flow limiter.')] }
        : { what: L(hyd ? 'Réservoir (bâche) : stocke l’huile et reçoit les retours ; il est à l’air libre.' : 'Échappement à l’atmosphère.', hyd ? 'Reservoir (tank): stores oil and receives returns; vented to atmosphere.' : 'Exhaust to atmosphere.'), use: L(hyd ? 'Au début (aspiration de la pompe) et à la fin (retour) de tout circuit hydraulique.' : 'Aux orifices d’échappement : l’air sort à la pression atmosphérique.', hyd ? 'At the start (pump suction) and end (return) of every hydraulic circuit.' : 'On exhaust ports: air leaves at atmospheric pressure.'), params: hyd ? [P('Volume', 'Il vaut en général 3 à 5 fois le débit de la pompe par minute : il permet à l’huile de refroidir et de se désaérer.', 'Volume', 'Usually 3–5 times the pump flow per minute: it lets oil cool and de-aerate.')] : [] }
    case 'fgauge':
      return { what: L('Appareil de mesure ou bouchon : affiche la pression (ou une autre grandeur) en un point du circuit sans modifier l’écoulement ; un bouchon ferme simplement un orifice.', 'Instrument or plug: displays pressure (or another quantity) at a point in the circuit without altering flow; a plug just closes a port.'), use: L('Pour contrôler les pressions pendant les essais et réglages, et visualiser en simulation les zones sous pression.', 'To check pressures during tests and setting, and to see pressurised zones in the simulation.'), params: [P('Étendue du manomètre', 'Elle doit se situer environ 1,5 fois au-dessus de la pression de service : trop petite le manomètre est endommagé, trop grande la lecture est imprécise.', 'Gauge range', 'It should be about 1.5 times the operating pressure: too small and the gauge is damaged, too large and reading is imprecise.')] }
    case 'flink':
      return { what: L('Appareil de conditionnement du fluide (filtre, régulateur, lubrificateur, sécheur, échangeur, raccord) : le fluide le traverse en étant traité sans changer de circuit.', 'Fluid conditioning device (filter, regulator, lubricator, dryer, heat exchanger, fitting): fluid passes through while being treated, without leaving the circuit.'), use: L(hyd ? 'Filtre : protège pompes et distributeurs de la pollution. Placé sur l’aspiration, le refoulement ou le retour.' : 'Unité de conditionnement en tête du circuit : filtre (élimine eau et poussières), régulateur (fixe la pression), lubrificateur (ajoute de l’huile).', hyd ? 'Filter: protects pumps and valves from contamination. Placed on suction, pressure or return.' : 'Conditioning unit at circuit head: filter (removes water and dust), regulator (sets pressure), lubricator (adds oil).'), params: [P(hyd ? 'Finesse de filtration (µm)' : 'Finesse de filtration et purge', hyd ? 'Plus la finesse est élevée, plus l’huile est propre et l’usure faible, mais plus le filtre se colmate vite.' : 'Un filtre fin (5 µm) protège les distributeurs ; la purge de condensats doit être vidée régulièrement (ou automatique), sinon l’eau passe dans le circuit.', hyd ? 'Filtration (µm)' : 'Filtration and drain', hyd ? 'The finer the filtration, the cleaner the oil and the lower the wear, but the faster the filter clogs.' : 'A fine filter (5 µm) protects valves; the condensate drain must be emptied regularly (or be automatic), otherwise water enters the circuit.'), press] }
    case 'fnet':
      return { what: L('Pièce élémentaire de distributeur : une case avec ses voies, utilisée pour composer son propre distributeur.', 'Valve building block: a single cell with its paths, used to compose your own valve.'), use: L('Pour comprendre ou dessiner le fonctionnement interne d’un distributeur : chaque case est une position du tiroir.', 'To understand or draw the internal operation of a valve: each cell is a spool position.'), params: [] }
    case 'cyl': {
      const single = f.single
      return { what: single ? L(`Vérin simple effet : un seul orifice ; la tige sort sous la pression ${fluid.fr}, et revient par un ressort ou la charge.`, `Single-acting cylinder: one port; the rod extends under pressure ${fluid.en} and returns by a spring or the load.`) : L(`Vérin double effet : deux orifices ; la pression ${fluid.fr} fait sortir ou rentrer la tige selon la chambre alimentée. Il développe un effort dans les deux sens.`, `Double-acting cylinder: two ports; pressure ${fluid.en} extends or retracts the rod depending on which chamber is fed. It develops force both ways.`), use: L('Pour pousser, tirer, serrer, lever : poste de serrage, poussoir de pièces, ouverture de porte.', 'To push, pull, clamp, lift: clamping station, part pusher, door opening.'), params: [P('Diamètre du piston', 'L’effort vaut pression × surface : à 6 bar, un piston de 40 mm pousse environ 750 N. Un piston trop petit ne vaincra pas la charge.', 'Piston diameter', 'Force = pressure × area: at 6 bar a 40 mm piston pushes about 750 N. A piston that is too small will not overcome the load.'), P('Course', 'C’est le déplacement de la tige ; elle doit être un peu supérieure au mouvement utile et les détecteurs de fin de course se règlent à ses extrémités.', 'Stroke', 'The rod travel; slightly more than the useful movement; end-of-stroke detectors are set at its ends.'), P('Vitesse', 'Elle se règle avec des limiteurs de débit : placés à l’échappement, ils donnent un mouvement régulier.', 'Speed', 'Set with flow limiters: placed on the exhaust they give a smooth movement.')], tip: L('Le repère (1A, 2A…) permet à un détecteur de se placer sur ce vérin.', 'The tag (1A, 2A…) lets a sensor be placed on this cylinder.') }
    }
    case 'valve': {
      const nums = portNumbers(d)
      const ports = Object.values(nums).filter(Boolean)
      const nNums = new Set(ports.filter((p) => /^\d$/.test(String(p)))).size
      const ways = nNums || d.ports.filter((p) => p.dir === 'up' || p.dir === 'down').length
      const act = f.a === 'elec' ? L('électrique (électrovanne)', 'electric (solenoid)') : f.a === 'man' ? L('manuelle', 'manual') : L('pneumatique (pilotage par pression)', 'pneumatic (pressure pilot)')
      const ret = f.b === 'spring' ? L('rappel par ressort : sans commande, il revient seul à sa position de repos (monostable)', 'spring return: with no command it goes back to rest on its own (monostable)') : f.b === 'none' ? L('pas de rappel ni de seconde commande', 'no return or second command') : L('seconde commande : le tiroir reste dans la dernière position commandée (bistable : il mémorise)', 'second command: the spool stays in the last commanded position (bistable: it remembers)')
      const nm = f.three ? L('trois positions : au centre (ressorts), les orifices sont dans un état particulier (fermés, à l’échappement ou sous pression)', 'three positions: at centre (springs) the ports are in a particular state (closed, exhausted or pressurised)') : L('deux positions', 'two positions')
      const pil = pilotNumbers(d)
      const coil = f.a === 'elec' ? solenoidNames('1', pil)[0].join(', ') : ''
      return { what: L(`Distributeur ${ways ? ways + ' voies' : ''} : oriente le fluide (${hyd ? 'huile' : 'air comprimé'}) vers les orifices voulus. Commande ${act.fr}. ${up(nm.fr)}. ${up(ret.fr)}.`, `${ways ? ways + '-way ' : ''}directional valve: routes the fluid (${hyd ? 'oil' : 'compressed air'}) to the chosen ports. ${up(act.en)} control. ${up(nm.en)}. ${up(ret.en)}.`), use: L('Il commande les mouvements d’un vérin : un 5/2 alimente tour à tour les deux chambres (sortie / rentrée) ; un 3/2 sert pour un vérin simple effet ou un signal ; un 5/3 permet l’arrêt en position intermédiaire.', 'It controls a cylinder’s movements: a 5/2 feeds the two chambers in turn (extend / retract); a 3/2 serves a single-acting cylinder or a signal; a 5/3 allows stopping in an intermediate position.'), params: [P('Numéros d’orifices (1, 2, 3, 4, 5)', 'Norme ISO 5599 : 1 = alimentation, 2 et 4 = utilisations (vers le vérin), 3 et 5 = échappements, 12/14 = commandes. Les respecter évite les erreurs de raccordement.', 'Port numbers (1, 2, 3, 4, 5)', 'ISO 5599: 1 = supply, 2 and 4 = outlets (to the cylinder), 3 and 5 = exhausts, 12/14 = pilot signals. Following them avoids piping errors.'), ...(coil ? [P('Repère de l’électrovanne (ex. 1YV14)', 'Le nom vient de la liaison établie quand elle est alimentée : 14 = 1 relié à 4, 12 = 1 relié à 2. Il doit être le même sur le schéma électrique pour que la simulation relie les deux.', 'Solenoid tag (e.g. 1YV14)', 'The name comes from the connection made when powered: 14 = 1 to 4, 12 = 1 to 2. It must be the same on the electrical diagram so that the simulation links them.')] as [L, L][] : []), P('Débit nominal', 'Il doit suffire pour la vitesse du vérin : un distributeur trop petit étrangle le débit et ralentit le mouvement.', 'Nominal flow', 'It must be enough for the cylinder speed: an undersized valve chokes flow and slows movement.')], tip: L(f.a === 'elec' ? 'En simulation, maintenez le clic sur une électrovanne pour la manœuvrer à la main (commande de secours).' : undefined as unknown as string, 'In simulation, hold the click on a solenoid to operate it by hand (manual override).') }
    }
    case 'check':
      return { what: L(f.pilot ? 'Clapet anti-retour piloté : laisse passer le fluide dans un sens et le bloque dans l’autre, sauf si une pression de pilotage le débloque.' : 'Clapet anti-retour : laisse passer le fluide dans un sens seulement, la bille se plaque sur son siège dans l’autre sens.', f.pilot ? 'Pilot-operated check valve: lets fluid pass one way and blocks the other, unless a pilot pressure releases it.' : 'Check valve: lets fluid pass in one direction only; the ball seats against the flow in the other.'), use: L(f.pilot ? 'Pour maintenir un vérin en position (charge suspendue) tant qu’on ne commande pas son déblocage.' : 'Pour maintenir une pression, éviter un retour de fluide ou, avec un limiteur, créer un limiteur de débit unidirectionnel.', f.pilot ? 'To hold a cylinder in position (suspended load) until its release is commanded.' : 'To hold a pressure, prevent back-flow, or with a restrictor build a one-way flow control.'), params: [P('Pression d’ouverture', 'Le ressort impose une petite pression minimale pour ouvrir le clapet ; elle doit rester faible devant la pression de service pour ne pas perdre d’énergie.', 'Cracking pressure', 'The spring requires a small minimum pressure to open; it should stay small compared with operating pressure to waste no energy.')] }
    case 'logic':
      return f.op === 'or'
        ? { what: L('Sélecteur de circuit (fonction OU) : la sortie est sous pression dès qu’une des deux entrées l’est ; un clapet à bille bouche l’entrée qui n’est pas alimentée.', 'Shuttle valve (OR function): the output is pressurised as soon as either input is; a ball seals the unpowered input.'), use: L('Pour commander un vérin depuis deux postes (deux boutons), l’un ou l’autre suffisant.', 'To command a cylinder from two stations (two buttons), either being enough.'), params: [] }
        : { what: L('Soupape à deux pressions (fonction ET) : la sortie n’est sous pression que si les deux entrées le sont en même temps.', 'Two-pressure valve (AND function): the output is pressurised only if both inputs are at once.'), use: L('Pour une commande à deux mains (sécurité presse) ou un verrouillage : il faut agir sur les deux pour obtenir le mouvement.', 'For two-hand control (press safety) or an interlock: both must act to get the movement.'), params: [] }
    case 'fthrottle':
      return { what: L(f.oneWay ? 'Limiteur de débit unidirectionnel : étrangle le fluide dans un sens (réglable) et le laisse passer librement dans l’autre par un clapet.' : 'Limiteur de débit réglable : étrangle le passage du fluide pour ralentir ce qui se trouve en aval.', f.oneWay ? 'One-way flow control valve: throttles fluid one way (adjustable) and lets it pass freely the other through a check.' : 'Adjustable flow restrictor: throttles the fluid to slow what is downstream.'), use: L('Pour régler la vitesse d’un vérin : placé à l’échappement (réglage « meter-out ») le mouvement est régulier ; placé à l’alimentation le vérin peut sauter.', 'To set a cylinder’s speed: on the exhaust (meter-out) movement is smooth; on the supply the cylinder may jerk.'), params: [P('Ouverture (%)', 'Elle règle le débit : plus l’ouverture est faible, plus le vérin est lent (vitesse proportionnelle à l’ouverture en simulation).', 'Opening (%)', 'It sets the flow: the smaller the opening, the slower the cylinder (speed proportional to opening in the simulation).')], tip: L('Dans les propriétés, réglez « Ouverture ».', 'In the properties, set “Opening”.') }
    case 'fpress':
      return { what: L('Pressostat : contact électrique qui change d’état quand la pression atteint un seuil.', 'Pressure switch: electrical contact that changes state when pressure reaches a threshold.'), use: L('Pour contrôler la présence de pression avant un cycle, signaler une chute de pression ou arrêter un compresseur.', 'To check that pressure exists before a cycle, signal a pressure drop or stop a compressor.'), params: [P('Seuil de commutation et hystérésis', 'Le seuil fixe la pression de commutation ; l’hystérésis (écart entre enclenchement et déclenchement) évite les battements autour du seuil.', 'Switching threshold and hysteresis', 'The threshold sets the switching pressure; hysteresis (gap between make and break) avoids chattering around it.'), P('Repère', 'Le contact électrique de même repère suit la pression : c’est le lien entre circuit pneumatique et circuit électrique.', 'Tag', 'The electrical contact with the same tag follows pressure: it is the link between pneumatic and electrical circuits.')] }
    case 'fpump':
      return { what: L('Pompe hydraulique : aspire l’huile dans le réservoir et la refoule sous pression ; elle crée le débit, la pression vient de la charge.', 'Hydraulic pump: draws oil from the reservoir and delivers it under pressure; it creates flow, pressure comes from the load.'), use: L('Au cœur du groupe hydraulique, entraînée par un moteur électrique. Elle débite en permanence : protégez-la par un limiteur de pression.', 'At the heart of the power pack, driven by an electric motor. It delivers continuously: protect it with a relief valve.'), params: [P('Cylindrée (cm³/tr) et débit (L/min)', 'Le débit = cylindrée × vitesse de rotation ; il fixe la vitesse des vérins.', 'Displacement (cm³/rev) and flow (L/min)', 'Flow = displacement × speed; it sets cylinder speed.'), press], tip: L('En simulation, la pompe ne refoule que si son aspiration est reliée à un réservoir.', 'In the simulation the pump only delivers if its suction is connected to a reservoir.') }
    case 'fmotor':
      return { what: L(`Moteur ${hyd ? 'hydraulique' : 'pneumatique'} : transforme la pression ${fluid.fr} en rotation d’un arbre.`, `${hyd ? 'Hydraulic' : 'Air'} motor: converts ${fluid.en} pressure into shaft rotation.`), use: L('Pour entraîner un convoyeur, un treuil, un outil sans moteur électrique (ambiances explosives, couple élevé à basse vitesse).', 'To drive a conveyor, winch or tool without an electric motor (explosive atmospheres, high torque at low speed).'), params: [P('Cylindrée et couple', 'Le couple dépend de la pression et de la cylindrée ; la vitesse dépend du débit.', 'Displacement and torque', 'Torque depends on pressure and displacement; speed depends on flow.'), P('Sens de rotation', 'Il dépend de l’orifice alimenté : un moteur à deux orifices tourne dans les deux sens.', 'Direction', 'It depends on which port is fed: a two-port motor turns both ways.')] }
  }
  return null
}

/** Repli pour les composants fluides sans modèle de simulation : explication d'après leur nom. */
function byName(d: SymbolDef): { what: L; use: L; params: [L, L][]; tip?: L } | null {
  const n = d.name.fr
  const hyd = d.domain === 'hydraulic'
  const press = P('Pression de service', hyd ? 'Elle doit rester inférieure à la pression maximale du composant (50 à 350 bar en hydraulique).' : 'Elle est en général de 6 bar ; ne jamais dépasser la pression maximale du composant.', 'Operating pressure', hyd ? 'It must stay below the component’s maximum (50–350 bar in hydraulics).' : 'Usually 6 bar; never exceed the component’s maximum pressure.')
  if (/servovalve/i.test(n)) return { what: L('Servovalve : distributeur à commande proportionnelle très précise, qui règle le débit en continu plutôt que de basculer en tout ou rien.', 'Servo valve: very precise proportional-control valve that varies flow continuously instead of switching on/off.'), use: L('Pour asservir la position ou la vitesse d’un vérin (presses, bancs d’essai, robots hydrauliques).', 'To control the position or speed of a cylinder (presses, test benches, hydraulic robots).'), params: [P('Débit nominal et temps de réponse', 'Ils définissent la précision et la rapidité d’asservissement.', 'Rated flow and response time', 'They define the accuracy and speed of the control loop.'), press] }
  if (/vanne/i.test(n)) return { what: L(/trois|3/i.test(n) ? 'Vanne trois voies : oriente le fluide d’une entrée vers l’une de deux sorties.' : 'Vanne : ouvre ou ferme le passage du fluide (commande manuelle, électromagnétique ou motorisée).', /trois|3/i.test(n) ? 'Three-way valve: directs fluid from one inlet to one of two outlets.' : 'Valve: opens or closes the fluid path (manual, solenoid or motorised).'), use: L('Pour isoler une partie du circuit (maintenance), dériver un débit ou purger.', 'To isolate part of the circuit (maintenance), divert a flow or bleed.'), params: [press] }
  if (/verin|vérin/i.test(n)) return { what: L('Vérin télescopique : plusieurs tiges emboîtées qui permettent une très grande course dans un faible encombrement.', 'Telescopic cylinder: several nested rods giving a very long stroke in a short body.'), use: L('Pour les bennes, plateformes élévatrices et autres applications où la place manque.', 'For tipper bodies, lift platforms and other space-limited applications.'), params: [press] }
  if (/pompe-moteur|pompe moteur/i.test(n)) return { what: L('Pompe-moteur : machine réversible qui fonctionne en pompe (entraînée) ou en moteur (entraînant) selon le sens de l’énergie.', 'Pump-motor: reversible machine that works as a pump (driven) or a motor (driving) depending on energy direction.'), use: L('Pour les transmissions hydrostatiques et la récupération d’énergie.', 'For hydrostatic transmissions and energy recovery.'), params: [press] }
  if (/distributeur/i.test(n)) return { what: L('Distributeur : oriente le fluide vers les orifices voulus selon la position de son tiroir.', 'Directional valve: routes fluid to chosen ports depending on spool position.'), use: L('Pour commander le mouvement d’un vérin ou d’un moteur.', 'To control the movement of a cylinder or motor.'), params: [press] }
  return null
}

// ───────────────────────── composition
const FALLBACK_ELEC: Card = { test: () => true, what: L('Composant de la bibliothèque électrique.', 'Component from the electrical library.'), use: L('Consultez sa désignation et ses bornes pour l’insérer dans votre schéma ; le nom indique sa fonction.', 'See its designation and terminals to place it in your diagram; the name states its function.') }

export function explain(def: SymbolDef, lang: Lang): Explain {
  const pick = (l: L) => l[lang]
  const title = def.name[lang] || def.name.fr
  const m = def.sim
  let what: L, use: L, tip: L | undefined
  let params: [L, L][] = []
  const fl = def.domain !== 'electrical' ? fluidCard(def, lang) ?? byName(def) : null
  if (fl) ({ what, use, params, tip } = { what: fl.what, use: fl.use, params: fl.params, tip: fl.tip })
  else {
    const card = ELEC.find((c) => c.test(def)) ?? FALLBACK_ELEC
    what = card.named ? L(`${title} : ${card.what.fr}`, `${title}: ${card.what.en}`) : card.what
    use = card.use
    params = card.params ?? []
    tip = card.tip
  }
  const sim: string[] = []
  const fr = lang === 'fr'
  if (m?.k === 'switch') {
    const nPoles = m.poles.length + (m.changeover?.length ?? 0)
    if (m.changeover?.length) sim.push(fr ? 'Contact inverseur : un contact au repos (NF) et un contact au travail (NO) partagent une borne commune.' : 'Changeover contact: a rest (NC) and a work (NO) contact share a common terminal.')
    else sim.push(fr ? `${m.nc ? 'Contact normalement fermé (NF) : conduit au repos, s’ouvre quand il est actionné.' : 'Contact normalement ouvert (NO) : ouvert au repos, se ferme quand il est actionné.'}${nPoles > 1 ? ` ${nPoles} pôles actionnés ensemble.` : ''}` : `${m.nc ? 'Normally closed (NC) contact: conducts at rest, opens when actuated.' : 'Normally open (NO) contact: open at rest, closes when actuated.'}${nPoles > 1 ? ` ${nPoles} poles actuated together.` : ''}`)
    if (m.delay) sim.push(fr ? `Contact temporisé (${m.delay === 'on' ? 'à l’enclenchement' : m.delay === 'off' ? 'au déclenchement' : 'aux deux'}) : le changement d’état est retardé ; réglez la durée dans les propriétés.` : `Timed contact: the state change is delayed; set the duration in the properties.`)
    if (m.ctl === 'momentary') sim.push(fr ? 'Simulation : maintenez le clic de souris pour appuyer ; il revient au repos au relâchement.' : 'Simulation: hold the mouse button to press; it returns to rest on release.')
    else if (m.ctl === 'toggle') sim.push(fr ? 'Simulation : cliquez pour le faire basculer (état maintenu).' : 'Simulation: click to toggle it (state is kept).')
    else if (m.ctl === 'coil') sim.push(fr ? 'Simulation : il change d’état tout seul quand la bobine de même repère est alimentée.' : 'Simulation: it changes state by itself when the coil with the same tag is powered.')
    else sim.push(fr ? 'Simulation : Alt + clic simule un défaut (contact collé ou coupé).' : 'Simulation: Alt + click simulates a fault (stuck or cut contact).')
  } else if (m?.k === 'coil') sim.push(fr ? 'Simulation : quand ses deux bornes reçoivent la tension, elle s’active et ses contacts de même repère changent d’état.' : 'Simulation: when both its terminals receive voltage it energises and the contacts with the same tag change state.')
  else if (m?.k === 'load') sim.push(fr ? `Simulation : ${m.role === 'lamp' ? 'elle s’allume' : m.role === 'motor' ? 'il tourne (et le courant est mesuré, Alt + clic simule une surcharge)' : 'il est actif'} quand il est alimenté.` : `Simulation: ${m.role === 'lamp' ? 'it lights' : m.role === 'motor' ? 'it spins (current is measured; Alt + click simulates an overload)' : 'it is active'} when powered.`)
  else if (m?.k === 'plc') sim.push(fr ? 'Simulation : le programme s’exécute en continu tant que L+ et M sont alimentés ; les sorties actionnent leurs contacts.' : 'Simulation: the program runs continuously while L+ and M are powered; outputs actuate their contacts.')
  else if (m?.k === 'transformer') sim.push(fr ? 'Simulation : le secondaire devient une source quand le primaire est alimenté.' : 'Simulation: the secondary becomes a source when the primary is powered.')
  else if (m?.k === 'source') sim.push(fr ? 'Simulation : impose une tension au conducteur auquel elle est reliée ; la tension se règle dans les propriétés.' : 'Simulation: imposes a voltage on the conductor it is connected to; set the voltage in the properties.')
  if (def.fluid) {
    const k = def.fluid.k
    if (k === 'cyl') sim.push(fr ? 'Simulation : la chambre sous pression est colorée en rouge, celle à l’échappement en bleu ; la tige entre et sort selon le distributeur.' : 'Simulation: the pressurised chamber is red, the exhausting one blue; the rod moves according to the valve.')
    else if (k === 'valve') sim.push(fr ? 'Simulation : le tiroir se déplace quand une commande est active ; rouge = pression, bleu = échappement.' : 'Simulation: the spool moves when a command is active; red = pressure, blue = exhaust.')
    else sim.push(fr ? 'Simulation : les conduites sont colorées selon la pression (rouge) ou l’échappement (bleu) qui les traverse.' : 'Simulation: lines are coloured by the pressure (red) or exhaust (blue) passing through them.')
  }
  const out = params.map(([n, w]) => ({ name: pick(n), why: pick(w) }))
  // réglages propres à la famille (calibre, courbe, plage…) : repris tels quels depuis la fiche des caractéristiques
  for (const fd of fieldsFor(def)) if (!out.some((p) => p.name.startsWith(fd.label[lang].slice(0, 8)))) out.push({ name: fd.label[lang], why: fd.help[lang] })
  if (m && (m.k === 'coil' || m.k === 'load') && !out.some((p) => /Tension|Rated voltage/.test(p.name))) out.push({ name: pick(VOLTS[0]), why: pick(VOLTS[1]) })
  if (m?.k === 'coil' && m.timer || (m?.k === 'switch' && m.delay)) out.push({ name: fr ? 'Temporisation (s)' : 'Delay (s)', why: fr ? 'Durée avant le changement d’état de ses contacts : à régler selon le temps de process voulu (ex. 5 s avant démarrage, temps de freinage).' : 'Time before its contacts change state: set to the wanted process time (e.g. 5 s before start, braking time).' })
  return { title, what: pick(what), use: pick(use), params: out, sim, tip: tip && pick(tip) ? pick(tip) : undefined }
}

